// AnsiView patch (see PATCHES.md): tests for the fixed width big integer and Montgomery ladder.

import XCTest

@testable import NIOSSH

final class SSHBigUIntTests: XCTestCase {
    /// (name, modulus, base, exponent, ladder bits, expected), from Python's pow() (an independent
    /// implementation), generated by a seeded script.
    static let powVectors: [(String, String, String, String, Int, String)] = [
        ("small", "5f385828a995624c941157b7ab8d1b95", "8e7720b554319e9e5995d2bc732b07", "827b39345daf5d96", 64, "3b44a8be09574dc9cc9b5fc02579ee1e"),
        ("odd1024", "7ef9e5d8415a9e11faa45dff9983a43465aab737b6137e86fc0550a19e45bdb54e82688f1cd3579adb8a9bcbd0535753df439ce022a753550a4235334ace85edd9b92d94a1e3cfed5343751fa5271ffc3c04953df61b6b9e3b84a49357a129943313ef4c1a172381dfd9e16c78b294921d8adff75801552880119d6dcae3d6a5", "17777fb585dee1331b050121968f6afdc9d86877597db759c04ef828253f7053637f5a3d2df1f48d27765af03f90494b87ea3d7baee0aef39b1cb0486be03ef211baaddd9195473ed4401a4e14154edc58370109b69e27b636fd2050522af32d26e4fd0f8b6cc43ab107a54922cb0770c512c35ad765a95c0d4232c8cfbf278", "ef19e4a6c7ea922d41115daca68ee30cc6a26f09c15756451af268f6c15ca4d601a5e24519b843daf1b684a61e20d0af340b54d62bcd334e919dac3c6727d151", 512, "2692f4a36726a0fe9e9d9ab0c8659c74b75792e0652602f9300f1706d3418d32864f591b2d18ea92797618beccdb5e1b86c140b581ef3483efee8282f53f3046d9a0321774c363acfc1f687a3b79ba1386aa5ff389d0e20d6bf5ffc10790bdd0ecb8d3637cf2043cea939511c5de4afa2761af14991e652e3e0655bda8d1d8f4"),
        ("g14base2", "", "2", "e2c31029ca31462bb350496db480c2d5dea56e274a1eab25c054ba402556d75c42232f9f4c8bce8cfb2cd8aa558fefaa41db9dc2eadd743e46a07faf54f26c50", 512, ""),
        ("g14rand", "", "", "b42c2347d3d6159ce036985e1a90245e0bbf01f0fddb654b77551b6ae77ffcc4336a2409564964b3c66a07945906cefe8fe0a1add10d034769aef8a2f41a097e", 512, ""),
        ("g16base2", "", "2", "c0c327060bf8534554490697faf048035f7ae949bee37b0665f710f4d11adaade5bcbd0e665745db071103163b86c30e1acd2c66057e976dbd9e9fd04fd22076", 512, ""),
        ("shortexp", "", "5", "1234567", 512, "")
    ]

    /// RFC 3526 group 14 and 16 primes as OpenSSL 3.6 prints its built in modp_2048 / modp_4096
    /// (checked against the RFC 3526 formulas, with pi from Machin's formula, before embedding).
    static let opensslModp2048 = ""
    static let opensslModp4096 = ""

    func testBytesRoundTrip() {
        let value = SSHBigUInt(bigEndianBytes: [0, 0, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09])
        XCTAssertEqual(value.bigEndianBytes, [0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09])
        XCTAssertEqual(
            value.bigEndianBytes(paddedTo: 12),
            [0, 0, 0, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09]
        )
        XCTAssertEqual(value.bitWidth, 65)
        XCTAssertEqual(SSHBigUInt(bigEndianBytes: []).bigEndianBytes, [])
        XCTAssertTrue(SSHBigUInt(bigEndianBytes: [0, 0]).isZero)
        XCTAssertEqual(SSHBigUInt(hex: "ff")!.bigEndianBytes, [0xFF])
    }

    func testComparisonAndSubtraction() {
        let a = SSHBigUInt(hex: "10000000000000000")!
        let b = SSHBigUInt(hex: "ffffffffffffffff")!
        XCTAssertTrue(b < a)
        XCTAssertFalse(a < b)
        XCTAssertEqual(a.subtracting(b), SSHBigUInt(hex: "1")!)
        XCTAssertEqual(SSHBigUInt(hex: "00ff")!, SSHBigUInt(hex: "ff")!)
    }

    func testMontgomeryRejectsEvenOrTinyModulus() {
        XCTAssertNil(SSHMontgomeryModulus(SSHBigUInt(hex: "10")!))
        XCTAssertNil(SSHMontgomeryModulus(SSHBigUInt(hex: "1")!))
        XCTAssertNil(SSHMontgomeryModulus(SSHBigUInt(bigEndianBytes: [])))
    }

    func testPowerMatchesPython() {
        for (name, modulus, base, exponent, bits, expected) in Self.powVectors {
            let context = SSHMontgomeryModulus(SSHBigUInt(hex: modulus)!)!
            let result = context.power(
                SSHBigUInt(hex: base)!,
                exponent: SSHBigUInt(hex: exponent)!,
                exponentBits: bits
            )
            XCTAssertEqual(result, SSHBigUInt(hex: expected)!, name)
        }
    }

    func testGroupPrimesMatchOpenSSL() {
        XCTAssertEqual(DiffieHellmanGroup.group14.prime, SSHBigUInt(hex: Self.opensslModp2048)!)
        XCTAssertEqual(DiffieHellmanGroup.group16.prime, SSHBigUInt(hex: Self.opensslModp4096)!)
        XCTAssertEqual(DiffieHellmanGroup.group14.prime.bitWidth, 2048)
        XCTAssertEqual(DiffieHellmanGroup.group16.prime.bitWidth, 4096)
        XCTAssertEqual(DiffieHellmanGroup.group14.generator, SSHBigUInt(hex: "2")!)
        XCTAssertEqual(DiffieHellmanGroup.group16.generator, SSHBigUInt(hex: "2")!)
    }

    func testDiffieHellmanAgreement() {
        let group = DiffieHellmanGroup.group14
        let context = SSHMontgomeryModulus(group.prime)!
        let a = SSHBigUInt(hex: "c0ffee" + String(repeating: "5a", count: 61))!
        let b = SSHBigUInt(hex: "beef01" + String(repeating: "a5", count: 61))!
        let ga = context.power(group.generator, exponent: a, exponentBits: 512)
        let gb = context.power(group.generator, exponent: b, exponentBits: 512)
        XCTAssertEqual(
            context.power(ga, exponent: b, exponentBits: 512),
            context.power(gb, exponent: a, exponentBits: 512)
        )
    }
}

extension SSHBigUInt {
    init?(hex: String) {
        var text = Substring(hex.count % 2 == 1 ? "0" + hex : hex)
        var bytes: [UInt8] = []
        while !text.isEmpty {
            guard let byte = UInt8(text.prefix(2), radix: 16) else { return nil }
            bytes.append(byte)
            text = text.dropFirst(2)
        }
        self.init(bigEndianBytes: bytes)
    }
}
